test("atomically matches, inserts, and idempotently links seller entries", () => {
  const path = createDatabase("idempotent"); const batch = input([{ Id: "opaque-1", SellerName: "seller", Name: "cafe grinder", Brand: "maker", Category: "kitchen" }, { Id: "opaque-2", SellerName: "seller", Name: "New product", Brand: "x'); DROP TABLE Product; --", Category: "tools" }]);
  const first = consolidate(batch, path, false, "run-1"); assert.deepEqual({ matched: first.matchedProducts, products: first.insertedProducts, links: first.insertedLinks }, { matched: 1, products: 1, links: 2 });
  const second = consolidate(batch, path, false, "run-2"); assert.deepEqual({ products: second.insertedProducts, links: second.insertedLinks, present: second.alreadyPresentLinks }, { products: 0, links: 0, present: 2 });
  const db = new DatabaseSync(path); try { assert.equal(db.prepare("SELECT COUNT(*) AS count FROM Product").get()?.count, 2); assert.equal(db.prepare("SELECT COUNT(*) AS count FROM SellerProduct").get()?.count, 2); assert.equal(db.prepare("SELECT Brand FROM Product WHERE Name = ?").get("New product")?.Brand, "x'); DROP TABLE Product; --"); assert.equal(db.prepare("PRAGMA foreign_key_check").all().length); } finally { db.close(); }
});
